/* nepui — Navigation Menu */

:is(.np-navigation-menu, [data-np-navigation-menu]) {
  --np-navigation-menu-gap: calc(var(--np-spacing) * 2);
  --np-navigation-menu-offset: 0.5rem;
  --np-navigation-menu-duration: 350ms;
  --np-navigation-menu-easing: cubic-bezier(0.22, 1, 0.36, 1);
  --np-navigation-menu-bg: var(--np-popover);
  --np-navigation-menu-color: var(
    --np-popover-foreground,
    var(--np-foreground)
  );
  --np-navigation-menu-shadow:
    0 0 0 1px color-mix(in oklab, var(--np-foreground) 10%, transparent),
    var(--np-shadow-md);

  position: relative;
  display: flex;
  flex: 1;
  align-items: center;
  justify-content: center;
  max-width: max-content;
}

:is(.np-navigation-menu-list, [data-np-navigation-menu-list]) {
  display: flex;
  flex: 1;
  align-items: center;
  justify-content: center;
  gap: var(--np-navigation-menu-gap);
  margin: 0;
  padding: 0;
  list-style: none;
}

:is(.np-navigation-menu-item, [data-np-navigation-menu-item]) {
  position: relative;
}

:is(.np-navigation-menu-trigger, [data-np-navigation-menu-trigger]) {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
  width: max-content;
  height: 2rem;
  margin: 0;
  padding: 0.375rem 0.625rem;
  border: 0;
  border-radius: var(--np-radius-lg);
  background: transparent;
  color: inherit;
  font: inherit;
  font-size: 0.875rem;
  font-weight: 500;
  line-height: 1.25rem;
  text-decoration: none;
  white-space: nowrap;
  cursor: pointer;
  outline: none;
  transition: background-color 150ms;
}

:is(.np-navigation-menu-trigger, [data-np-navigation-menu-trigger]):is(
  :hover,
  :focus
) {
  background: var(--np-muted);
}

:is(.np-navigation-menu-trigger, [data-np-navigation-menu-trigger]):is(
  [data-popup-open],
  [aria-expanded="true"],
  [data-active]
) {
  background: color-mix(in oklab, var(--np-muted) 50%, transparent);
}

:is(.np-navigation-menu-trigger, [data-np-navigation-menu-trigger]):is(
    [data-popup-open],
    [aria-expanded="true"]
  ):is(:hover, :focus) {
  background: var(--np-muted);
}

:is(
  .np-navigation-menu-trigger,
  [data-np-navigation-menu-trigger]
):focus-visible {
  outline: 2px solid var(--np-ring);
  outline-offset: -2px;
}

:is(.np-navigation-menu-trigger, [data-np-navigation-menu-trigger]):disabled {
  opacity: 0.5;
  pointer-events: none;
}

:is(.np-navigation-menu-trigger-icon, [data-np-navigation-menu-trigger-icon]) {
  position: relative;
  inset-block-start: 1px;
  flex: none;
  width: 0.75rem;
  height: 0.75rem;
  margin-inline-start: calc(var(--np-spacing) * 1);
  transition: transform 300ms;
}

:is(.np-navigation-menu-trigger, [data-np-navigation-menu-trigger]):is(
    [data-popup-open],
    [aria-expanded="true"]
  )
  :is(
    .np-navigation-menu-trigger-icon,
    [data-np-navigation-menu-trigger-icon]
  ) {
  transform: rotate(180deg);
}

:is(.np-navigation-menu-link, [data-np-navigation-menu-link]) {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem;
  border-radius: var(--np-radius-md);
  color: inherit;
  font-size: 0.875rem;
  line-height: 1.25rem;
  text-decoration: none;
  outline: none;
  transition: background-color 150ms;
}

:is(.np-navigation-menu-link, [data-np-navigation-menu-link]):is(
  :hover,
  :focus
) {
  background: var(--np-muted);
}

:is(.np-navigation-menu-link, [data-np-navigation-menu-link]):is(
  [data-active],
  [aria-current="page"]
) {
  background: color-mix(in oklab, var(--np-muted) 50%, transparent);
}

:is(.np-navigation-menu-link, [data-np-navigation-menu-link]):is(
    [data-active],
    [aria-current="page"]
  ):is(:hover, :focus) {
  background: var(--np-muted);
}

:is(.np-navigation-menu-link, [data-np-navigation-menu-link]):focus-visible {
  outline: 2px solid var(--np-ring);
  outline-offset: -2px;
}

:is(.np-navigation-menu-link, [data-np-navigation-menu-link]) > svg {
  flex: none;
  width: 1rem;
  height: 1rem;
}

:is(.np-navigation-menu-link-text, [data-np-navigation-menu-link-text]) {
  display: flex;
  flex-direction: column;
  gap: calc(var(--np-spacing) * 1);
}

:is(.np-navigation-menu-link-title, [data-np-navigation-menu-link-title]) {
  font-weight: 500;
  line-height: 1;
}

:is(
  .np-navigation-menu-link-description,
  [data-np-navigation-menu-link-description]
) {
  display: -webkit-box;
  overflow: hidden;
  color: var(--np-muted-foreground);
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  line-clamp: 2;
}

:is(.np-navigation-menu-content, [data-np-navigation-menu-content]) {
  box-sizing: border-box;
  width: auto;
  height: 100%;
  padding: calc(var(--np-spacing) * 1);
  border: 1px solid var(--np-border);
  border-radius: var(--np-radius-lg);
  box-shadow: var(--np-shadow-md);
  background-color: var(--np-popover);
}

:is(.np-navigation-menu-positioner, [data-np-navigation-menu-positioner]) {
  z-index: 50;
  isolation: isolate;
  width: var(--positioner-width);
  height: var(--positioner-height);
  max-width: var(--available-width);
  background-color: var(--navigation-menu-bg);
  transition-property: top, left, right, bottom;
  transition-duration: var(--np-navigation-menu-duration);
  transition-timing-function: var(--np-navigation-menu-easing);
}

:is(
  .np-navigation-menu-positioner,
  [data-np-navigation-menu-positioner]
)[data-instant] {
  transition: none;
}

:is(.np-navigation-menu-popup, [data-np-navigation-menu-popup]) {
  position: relative;
  width: var(--popup-width);
  height: var(--popup-height);
  border-radius: var(--np-radius-lg);
  background: var(--np-navigation-menu-bg);
  color: var(--np-navigation-menu-color);
  box-shadow: var(--np-navigation-menu-shadow);
  outline: none;
  transform-origin: var(--transform-origin);
  transition-property: opacity, transform, width, height, scale, translate;
  transition-duration: var(--np-navigation-menu-duration);
  transition-timing-function: var(--np-navigation-menu-easing);
}

:is(.np-navigation-menu-popup, [data-np-navigation-menu-popup]):is(
  [data-starting-style],
  [data-ending-style]
) {
  opacity: 0;
  scale: 0.9;
}

:is(
  .np-navigation-menu-popup,
  [data-np-navigation-menu-popup]
)[data-ending-style] {
  transition-duration: 150ms;
}

:is(.np-navigation-menu-viewport, [data-np-navigation-menu-viewport]) {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
}

:is(.np-navigation-menu-popup, [data-np-navigation-menu-popup])
  :is(.np-navigation-menu-content, [data-np-navigation-menu-content]) {
  transition-property: opacity, transform, translate;
  transition-duration: var(--np-navigation-menu-duration);
  transition-timing-function: var(--np-navigation-menu-easing);
}

:is(.np-navigation-menu-content, [data-np-navigation-menu-content]):is(
  [data-starting-style],
  [data-ending-style]
) {
  opacity: 0;
}

:is(
    .np-navigation-menu-content,
    [data-np-navigation-menu-content]
  )[data-starting-style][data-activation-direction="left"] {
  translate: -50% 0;
}

:is(
    .np-navigation-menu-content,
    [data-np-navigation-menu-content]
  )[data-starting-style][data-activation-direction="right"] {
  translate: 50% 0;
}

:is(
    .np-navigation-menu-content,
    [data-np-navigation-menu-content]
  )[data-ending-style][data-activation-direction="left"] {
  translate: 50% 0;
}

:is(
    .np-navigation-menu-content,
    [data-np-navigation-menu-content]
  )[data-ending-style][data-activation-direction="right"] {
  translate: -50% 0;
}

:is(.np-navigation-menu-item, [data-np-navigation-menu-item])
  > :is(.np-navigation-menu-content, [data-np-navigation-menu-content]) {
  position: absolute;
  inset-block-start: calc(100% + var(--np-navigation-menu-offset));
  inset-inline-start: 0;
  z-index: 50;
  display: none;
  min-width: max-content;
  height: auto;
  border-radius: var(--np-radius-lg);
  background: var(--np-navigation-menu-bg);
  color: var(--np-navigation-menu-color);
  box-shadow: var(--np-navigation-menu-shadow);
  opacity: 0;
  translate: 0 -calc(var(--np-spacing) * 1);
  scale: 0.95;
  transform-origin: top;
  transition-property: opacity, translate, scale, display;
  transition-duration: 200ms;
  transition-timing-function: var(--np-navigation-menu-easing);
  transition-behavior: allow-discrete;
}

:is(.np-navigation-menu-item, [data-np-navigation-menu-item])
  > :is(
    .np-navigation-menu-content,
    [data-np-navigation-menu-content]
  )::before {
  content: "";
  position: absolute;
  inset-block: calc(var(--np-navigation-menu-offset) * -1) auto;
  inset-inline: 0;
  height: var(--np-navigation-menu-offset);
}

:is(.np-navigation-menu-item, [data-np-navigation-menu-item])[data-open]
  > :is(.np-navigation-menu-content, [data-np-navigation-menu-content]) {
  display: block;
  opacity: 1;
  translate: 0 0;
  scale: 1;
}

@starting-style {
  :is(.np-navigation-menu-item, [data-np-navigation-menu-item])[data-open]
    > :is(.np-navigation-menu-content, [data-np-navigation-menu-content]) {
    opacity: 0;
    translate: 0 -calc(var(--np-spacing) * 1);
    scale: 0.95;
  }
}

@media (prefers-reduced-motion: reduce) {
  :is(.np-navigation-menu-positioner, [data-np-navigation-menu-positioner]),
  :is(.np-navigation-menu-popup, [data-np-navigation-menu-popup]),
  :is(.np-navigation-menu-content, [data-np-navigation-menu-content]),
  :is(
    .np-navigation-menu-trigger-icon,
    [data-np-navigation-menu-trigger-icon]
  ) {
    transition: none;
  }
}

;(function () {
  var SELECTOR = ".np-navigation-menu, [data-np-navigation-menu]"
  var ITEM = ".np-navigation-menu-item, [data-np-navigation-menu-item]"
  var CONTENT = ".np-navigation-menu-content, [data-np-navigation-menu-content]"
  var LINK = ".np-navigation-menu-link, [data-np-navigation-menu-link], a[href]"
  var CHEVRON =
    '<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="np-navigation-menu-trigger-icon" aria-hidden="true"><path d="m6 9 6 6 6-6" /></svg>'
  var uid = 0
  var instances = new WeakMap()

  function child(parent, selector) {
    return Array.prototype.filter.call(parent.children, function (c) {
      return c.matches(selector)
    })[0]
  }

  function init(root) {
    if (instances.has(root)) return instances.get(root)

    var openDelay = Number(root.getAttribute("data-delay"))
    var closeDelay = Number(root.getAttribute("data-close-delay"))
    if (isNaN(openDelay) || root.getAttribute("data-delay") === null)
      openDelay = 50
    if (isNaN(closeDelay) || root.getAttribute("data-close-delay") === null)
      closeDelay = 50

    var list = root.querySelector(
      ".np-navigation-menu-list, [data-np-navigation-menu-list]"
    )
    var items = Array.prototype.slice
      .call(list.children)
      .filter(function (child) {
        return child.matches(ITEM)
      })
    var current = null
    var timer = 0

    items.forEach(function (item) {
      var trigger = child(item, "button")
      var content = child(item, CONTENT)
      if (!trigger || !content) return
      if (!item.hasAttribute("data-value"))
        item.setAttribute("data-value", "item-" + ++uid)
      if (!content.id) content.id = "np-navigation-menu-content-" + ++uid
      trigger.setAttribute("aria-expanded", "false")
      trigger.setAttribute("aria-controls", content.id)
      if (
        !trigger.querySelector(
          ".np-navigation-menu-trigger-icon, [data-np-navigation-menu-trigger-icon]"
        )
      ) {
        trigger.insertAdjacentHTML("beforeend", CHEVRON)
      }
    })

    function triggerOf(item) {
      return child(item, "button[aria-controls]")
    }

    function set(item, value, silent) {
      if (item === current && value) return
      if (!value && item !== current) return
      var previous = current
      if (previous) {
        previous.removeAttribute("data-open")
        var t = triggerOf(previous)
        if (t) t.setAttribute("aria-expanded", "false")
      }
      current = value ? item : null
      if (current) {
        current.setAttribute("data-open", "")
        triggerOf(current).setAttribute("aria-expanded", "true")
      }
      if (!silent) {
        root.dispatchEvent(
          new CustomEvent("np-navigation-menu-change", {
            bubbles: true,
            detail: {
              value: current ? current.getAttribute("data-value") : null,
            },
          })
        )
      }
    }

    function later(fn, delay) {
      clearTimeout(timer)
      if (delay > 0) timer = setTimeout(fn, delay)
      else fn()
    }

    function close() {
      clearTimeout(timer)
      if (current) set(current, false)
    }

    function entries() {
      return items
        .map(function (item) {
          return triggerOf(item) || child(item, "a")
        })
        .filter(Boolean)
    }

    items.forEach(function (item) {
      var trigger = triggerOf(item)
      var content = child(item, CONTENT)

      item.addEventListener("pointerenter", function (event) {
        if (event.pointerType === "touch") return
        clearTimeout(timer)
        if (!trigger || !content) {
          later(close, closeDelay)
          return
        }
        later(
          function () {
            set(item, true)
          },
          current ? 0 : openDelay
        )
      })
      item.addEventListener("pointerleave", function (event) {
        if (event.pointerType === "touch" || item !== current) return
        later(close, closeDelay)
      })

      if (!trigger || !content) return

      trigger.addEventListener("click", function () {
        clearTimeout(timer)
        set(item, item !== current)
      })

      trigger.addEventListener("keydown", function (event) {
        if (event.key === "ArrowDown") {
          event.preventDefault()
          set(item, true)
          var first = content.querySelector(LINK)
          if (first) first.focus()
        }
      })

      content.addEventListener("keydown", function (event) {
        var links = Array.prototype.slice.call(content.querySelectorAll(LINK))
        var index = links.indexOf(document.activeElement)
        if (event.key === "ArrowDown" || event.key === "ArrowUp") {
          event.preventDefault()
          if (!links.length) return
          var next = event.key === "ArrowDown" ? index + 1 : index - 1
          if (next >= links.length) next = 0
          if (next < 0) next = links.length - 1
          links[next].focus()
        }
      })
    })

    root.addEventListener("keydown", function (event) {
      if (event.key === "Escape" && current) {
        var t = triggerOf(current)
        close()
        if (t) t.focus()
        return
      }
      var all = entries()
      var index = all.indexOf(event.target)
      if (index === -1) return
      var rtl = getComputedStyle(root).direction === "rtl"
      var next = -1
      if (event.key === "ArrowRight") next = rtl ? index - 1 : index + 1
      else if (event.key === "ArrowLeft") next = rtl ? index + 1 : index - 1
      else if (event.key === "Home") next = 0
      else if (event.key === "End") next = all.length - 1
      else return
      event.preventDefault()
      if (next >= all.length) next = 0
      if (next < 0) next = all.length - 1
      all[next].focus()
    })

    root.addEventListener("focusout", function (event) {
      if (!current) return
      var to = event.relatedTarget
      if (to && root.contains(to)) {
        var item = to.closest(ITEM)
        if (item !== current && current) close()
        return
      }
      if (
        to === null &&
        event.target.closest &&
        event.target.closest(ITEM) === current &&
        !root.matches(":hover")
      ) {
        close()
      }
    })

    document.addEventListener("pointerdown", function (event) {
      if (current && !root.contains(event.target)) close()
    })

    var api = {
      open: function (value) {
        var item = items.filter(function (i) {
          return i.getAttribute("data-value") === value
        })[0]
        if (item && triggerOf(item)) set(item, true)
      },
      close: close,
    }
    instances.set(root, api)
    return api
  }

  function initAll(scope) {
    var nodes = (scope || document).querySelectorAll(SELECTOR)
    for (var i = 0; i < nodes.length; i++) init(nodes[i])
  }

  window.NepuiNavigationMenu = {
    init: init,
    initAll: initAll,
    get: function (root) {
      return instances.get(root) || null
    },
  }

  if (document.readyState === "loading")
    document.addEventListener("DOMContentLoaded", function () {
      initAll()
    })
  else initAll()
})()
